glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform ARGS{
  float width;
  float strength;
  float timerScale;
};
void main () {
  vec4 color = vec4(1, 1, 1, 1);
  color *= texture2D(texture, v_uv0);
  float k = 0.5;
  float time_step = -width;
  time_step += mod(cc_time.x * timerScale,1.0 + 2.0 * width);
  if (v_uv0.x >= -v_uv0.y * k + time_step && v_uv0.x <= -v_uv0.y * k + width + time_step ) {
    color *= strength;
  }
  gl_FragColor = color;
}

